"""Unit tests for the order-paid -> invoice worker. Written first; each names a failure, not only the success.

Run: python3 -m unittest -v test_worker   (from this folder)
"""
import json
import sqlite3
import unittest

import migrations
from worker import Config, InvoiceWorker, Outcome

CONFIG = Config(db_timeout_s=5.0, max_deliveries=5)


class FakeDelivery:
    """One delivery of a message; records what the worker did with it."""

    def __init__(self, body, message_id="m-1", delivery_count=1):
        self.body = body if isinstance(body, (bytes, str)) else json.dumps(body)
        self.message_id = message_id
        self.delivery_count = delivery_count
        self.acked = False
        self.dead_lettered = None  # reason string once dead-lettered
        self.nacked = False

    def ack(self):
        self.acked = True

    def dead_letter(self, reason):
        self.dead_lettered = reason

    def nack(self):
        self.nacked = True


def paid(order_id="o-1", amount_cents=1999, currency="EUR"):
    return {"order_id": order_id, "amount_cents": amount_cents, "currency": currency}


class FailingConnection:
    """A connection whose writes fail as a locked/unavailable database would."""

    def __init__(self, real):
        self.real = real

    def execute(self, sql, params=()):
        if sql.lstrip().upper().startswith("INSERT"):
            raise sqlite3.OperationalError("database is locked")
        return self.real.execute(sql, params)

    def commit(self):
        self.real.commit()

    def rollback(self):
        self.real.rollback()


class Base(unittest.TestCase):
    def setUp(self):
        self.db = sqlite3.connect(":memory:")
        migrations.up(self.db)
        self.worker = InvoiceWorker(self.db, CONFIG)

    def rows(self):
        return self.db.execute("SELECT order_id, amount_cents, currency FROM invoices ORDER BY order_id").fetchall()


class TestHappyPath(Base):
    def test_one_delivery_makes_one_invoice_and_acks_after_commit(self):
        d = FakeDelivery(paid())
        self.assertEqual(self.worker.handle(d), Outcome.CREATED)
        self.assertTrue(d.acked)
        self.assertEqual(self.rows(), [("o-1", 1999, "EUR")])


class TestSecondRun(Base):
    def test_redelivery_of_same_message_leaves_state_as_after_one(self):
        first, again = FakeDelivery(paid()), FakeDelivery(paid(), delivery_count=2)
        self.worker.handle(first)
        after_one = self.rows()
        self.assertEqual(self.worker.handle(again), Outcome.DUPLICATE)
        self.assertEqual(self.rows(), after_one)
        self.assertTrue(again.acked, "a duplicate must be acked or the queue redelivers it forever")

    def test_republished_message_with_new_message_id_is_still_one_invoice(self):
        self.worker.handle(FakeDelivery(paid(), message_id="m-1"))
        self.worker.handle(FakeDelivery(paid(), message_id="m-2"))
        self.assertEqual(len(self.rows()), 1)

    def test_same_order_with_different_amount_is_dead_lettered_not_overwritten(self):
        self.worker.handle(FakeDelivery(paid(amount_cents=1999)))
        d = FakeDelivery(paid(amount_cents=2500), message_id="m-2")
        self.assertEqual(self.worker.handle(d), Outcome.DEAD_LETTERED)
        self.assertIn("conflict", d.dead_lettered)
        self.assertEqual(self.rows(), [("o-1", 1999, "EUR")])

    def test_many_orders_each_redelivered_give_one_invoice_each(self):
        for n in range(3):
            for _ in range(2):
                self.worker.handle(FakeDelivery(paid(order_id="o-%d" % n)))
        self.assertEqual([r[0] for r in self.rows()], ["o-0", "o-1", "o-2"])


class TestBadInput(Base):
    def assert_dead_lettered_without_row(self, body):
        d = FakeDelivery(body)
        self.assertEqual(self.worker.handle(d), Outcome.DEAD_LETTERED)
        self.assertFalse(d.acked)
        self.assertTrue(d.dead_lettered)
        self.assertEqual(self.rows(), [])

    def test_empty_body(self):
        self.assert_dead_lettered_without_row(b"")

    def test_not_json(self):
        self.assert_dead_lettered_without_row(b"{not json")

    def test_missing_order_id(self):
        self.assert_dead_lettered_without_row({"amount_cents": 100, "currency": "EUR"})

    def test_negative_amount(self):
        self.assert_dead_lettered_without_row(paid(amount_cents=-1))

    def test_amount_not_integer(self):
        self.assert_dead_lettered_without_row(paid(amount_cents="19.99"))

    def test_zero_amount_is_accepted_boundary(self):
        d = FakeDelivery(paid(amount_cents=0))
        self.assertEqual(self.worker.handle(d), Outcome.CREATED)


class TestFailingDependency(Base):
    def test_failed_write_is_not_acked_and_not_hidden(self):
        worker = InvoiceWorker(FailingConnection(self.db), CONFIG)
        d = FakeDelivery(paid())
        with self.assertLogs("invoice_worker", level="WARNING") as logs:
            outcome = worker.handle(d)
        self.assertEqual(outcome, Outcome.RETRY)
        self.assertFalse(d.acked, "a failed write must never be acked")
        self.assertTrue(d.nacked)
        self.assertEqual(self.rows(), [])
        self.assertIn("o-1", "\n".join(logs.output))

    def test_failed_write_at_retry_limit_is_dead_lettered(self):
        worker = InvoiceWorker(FailingConnection(self.db), CONFIG)
        d = FakeDelivery(paid(), delivery_count=CONFIG.max_deliveries)
        self.assertEqual(worker.handle(d), Outcome.DEAD_LETTERED)
        self.assertFalse(d.acked)
        self.assertIn("retry limit", d.dead_lettered)

    def test_unexpected_error_propagates_after_nack(self):
        class Broken:
            def execute(self, *a):
                raise RuntimeError("bug")

            def rollback(self):
                pass

        d = FakeDelivery(paid())
        with self.assertRaises(RuntimeError):
            InvoiceWorker(Broken(), CONFIG).handle(d)
        self.assertFalse(d.acked)
        self.assertTrue(d.nacked)


class TestConfig(unittest.TestCase):
    def test_reads_environment(self):
        c = Config.from_env({"INVOICE_DB_TIMEOUT_S": "4", "INVOICE_MAX_DELIVERIES": "7"})
        self.assertEqual((c.db_timeout_s, c.max_deliveries), (4.0, 7))

    def test_missing_setting_fails_at_start_up(self):
        with self.assertRaises(KeyError):
            Config.from_env({"INVOICE_DB_TIMEOUT_S": "4"})

    def test_timeout_must_fit_inside_visibility_window(self):
        with self.assertRaises(ValueError):
            Config.from_env({"INVOICE_DB_TIMEOUT_S": "30", "INVOICE_MAX_DELIVERIES": "5"})


class TestMigration(unittest.TestCase):
    def setUp(self):
        self.db = sqlite3.connect(":memory:")
        # the shape the first draft wrote to: no key on order_id
        self.db.execute(migrations.LEGACY_TABLE)

    def index_names(self):
        return [r[1] for r in self.db.execute("PRAGMA index_list(invoices)")]

    def test_forward_and_back_on_fixture_keeps_rows(self):
        self.db.execute("INSERT INTO invoices (order_id, amount_cents, currency) VALUES ('o-1', 10, 'EUR')")
        migrations.up(self.db)
        self.assertIn(migrations.INDEX, self.index_names())
        migrations.down(self.db)
        self.assertNotIn(migrations.INDEX, self.index_names())
        self.assertEqual(self.db.execute("SELECT COUNT(*) FROM invoices").fetchone()[0], 1)
        migrations.up(self.db)  # forward again after back
        self.assertIn(migrations.INDEX, self.index_names())

    def test_existing_duplicates_stop_the_migration_and_delete_nothing(self):
        for _ in range(2):
            self.db.execute("INSERT INTO invoices (order_id, amount_cents, currency) VALUES ('o-1', 10, 'EUR')")
        with self.assertRaises(migrations.DuplicateInvoices) as caught:
            migrations.up(self.db)
        self.assertIn("o-1", str(caught.exception))
        self.assertEqual(self.db.execute("SELECT COUNT(*) FROM invoices").fetchone()[0], 2)
        self.assertNotIn(migrations.INDEX, self.index_names())

    def test_old_reader_still_works_on_new_shape(self):
        migrations.up(self.db)
        self.db.execute("INSERT INTO invoices (order_id, amount_cents, currency) VALUES ('o-1', 10, 'EUR')")
        self.assertEqual(self.db.execute("SELECT order_id, amount_cents FROM invoices").fetchall(), [("o-1", 10)])


if __name__ == "__main__":
    unittest.main()
